use Filament\Forms\Components\{Select,TextInput,Textarea,Toggle,DateTimePicker,Placeholder};
use Filament\Tables\Table;
use Filament\Tables\Columns\TextColumn;
use Filament\Actions\{EditAction,Action};
class SponsorshipResource extends Resource {
 protected static ?string $model=Sponsorship::class;protected static ?string $modelLabel='Dossier de sponsoring';protected static ?string $pluralModelLabel='Sponsors · épreuves et événement';protected static string|\UnitEnum|null $navigationGroup='3 · Mobiliser';protected static ?int $navigationSort=35;
 public static function form(Schema $schema): Schema {return $schema->columns(2)->components([
 Select::make('event_project_id')->label('Édition')->relationship('eventProject','name')->required()->live()->disabledOn('edit'),TextInput::make('name')->label('Dossier')->required(),Select::make('scope')->label('Périmètre')->options(['activity'=>'Une épreuve officielle','main'=>'Sponsor principal · 1 place','secondary'=>'Partenaire secondaire · 3 places'])->required()->live(),Select::make('purpose')->label('Affectation')->options(['general'=>'Épreuve / événement','cups'=>'Gobelets · un des trois partenaires'])->required(),Select::make('secondary_slot')->label('Slot secondaire')->options([1=>'1',2=>'2',3=>'3 · proposé aux gobelets']),Select::make('activity_id')->label('Épreuve')->options(fn(Get $get)=>\App\Models\Activity::where('event_project_id',$get('event_project_id'))->where('track','official')->pluck('name','id'))->searchable(),Select::make('prospect_id')->label('Prospect à suivre en tournée')->options(fn(Get $get)=>\App\Models\Prospect::where('event_project_id',$get('event_project_id'))->pluck('name','id'))->searchable(),TextInput::make('sponsor_name')->label('Nom du sponsor convenu'),TextInput::make('dealer_name')->label('Concessionnaire / partenaire de la marque'),TextInput::make('website_url')->label('Site HTTPS')->url(),Textarea::make('target_profile')->label('Cible et pertinence'),Textarea::make('pitch')->label('Proposition, photos, démonstration et contreparties'),Textarea::make('source')->label('Sources / statut de la piste'),Select::make('status')->label('État')->options(['prospecting'=>'À prospecter','contacted'=>'Contact engagé','agreed'=>'Accord acquis, paiement distinct','cancelled'=>'Annulé'])->required(),DateTimePicker::make('agreed_at')->label('Accord reçu le')->timezone('Europe/Lisbon'),TextInput::make('cash_pledged_cents')->label('Montant TTC promis, centimes')->integer()->minValue(0),Textarea::make('in_kind')->label('Matériel ou services apportés · pas de trésorerie fictive'),Textarea::make('agreement_evidence')->label('Convention, échéances, annulation et justificatif'),Textarea::make('web_rights')->label('Visibilité web garantie, périmètre et droits de communication'),Select::make('budget_line_id')->label('Recette budgétaire existante · jamais une seconde recette')->options(fn(Get $get)=>\App\Models\BudgetLine::whereHas('scenario',fn($q)=>$q->where('event_project_id',$get('event_project_id')))->where('kind','revenue')->get()->mapWithKeys(fn($l)=>[$l->id=>$l->scenario->name.' · '.$l->name]))->searchable(),Placeholder::make('funding')->label('Préfinancement effectif')->content(fn(?Sponsorship $record)=>$record?'Accord : '.($record->agreed()?'oui':'non').' · paiement rapproché : '.\App\Domain\Finance\Money::format($record->funding()['paid_cents']).' · matériel : '.($record->funding()['complete']?'chiffré':'incomplet').'. Les apports en nature ne diminuent un coût qu’après révision documentée de son poste.':'Enregistrer le dossier.'),Toggle::make('is_public')->label('Publier le partenaire convenu sur le site'),DateTimePicker::make('print_approved_at')->label('BAT du lot imprimé accepté le')->timezone('Europe/Lisbon'),Textarea::make('print_evidence')->label('Lot, version du visuel, tirage, date limite et preuve BAT')->helperText('Web uniquement garanti au départ. Les flyers déjà imprimés ne sont jamais promis rétroactivement.')->columnSpanFull()]);}
 public static function table(Table $table): Table {return $table->groups([\Filament\Tables\Grouping\Group::make('scope')->label('Périmètre')->collapsible()])->defaultGroup('scope')->columns([TextColumn::make('name')->label('Dossier')->searchable()->wrap(),TextColumn::make('activity.name')->label('Épreuve'),TextColumn::make('prospect.name')->label('Prospect'),TextColumn::make('sponsor_name')->label('Sponsor convenu'),TextColumn::make('status')->badge(),TextColumn::make('paid')->label('Rapproché')->state(fn(Sponsorship $record)=>\App\Domain\Finance\Money::format($record->funding()['paid_cents']))])->filters([\Filament\Tables\Filters\SelectFilter::make('status')->options(['prospecting'=>'À prospecter','contacted'=>'Contact engagé','agreed'=>'Accord acquis','cancelled'=>'Annulé'])])->recordActions([EditAction::make()->modalWidth('7xl')]);}
 public static function getPages(): array {return ['index'=>\App\Filament\Resources\SponsorshipResource\Pages\ManageRecords::route('/')];}
}
